import { useNavigate } from "react-router-dom";

function Login() {

    function handleLogin() {
        navigate("/main");
    }

    return (
        <div>
            <h1>Login</h1>
            <button onClick={handleLogin}>Login</button>
        </div>
    )
}

export default Login;
